Method.Implementation:
  set tSC = $$$OK


  //set timeOut = ..TimeInSecs

 	Set timeOut = ##class(Ens.Director).GetHostSettingValue("IHC.ITF.CORERULES.Service.CoreSoapPort","ServiceTimeOut", .sc)
 //	
 	if (( timeOut = "") || (timeOut <=0 ))
 	{ 
	   set timeOut = 20 //If we do not have system value, ser Default CAQH CORERULES timeout value.

 	}

  #dim statement As %SQL.Statement = ##class(%SQL.Statement).%New()

  set logFile = "/itf-share/itf-tmp/270-RT_In/log/AbortQueue.txt"
  set fileObj = ##class(%File).%New(logFile)



  If ##class(%File).Exists(logFile)
  {
  	set status = fileObj.Open("W")
  }
  else
  {
	  set status = fileObj.Open("WN")
  }


  For ind=1:1:$L(..Source, ",")
  {
  	set srcComp = $P(..Source,",", ind)

  	if (srcComp '= "")
  	{
			set tSC = statement.%PrepareClassQuery("Ens.Queue","EnumerateItem")
			#dim rset As %SQL.StatementResult = statement.%Execute(srcComp, "") 

			while rset.%Next() 
			{

				set id = rset.%Get("Index")
				set msgId = rset.%Get("MessageId")

				&SQL(SELECT
					DATEDIFF('ss',TimeCreated, GETUTCDATE(CURRENT_TIMESTAMP) ) into tmdiff
					FROM Ens.MessageHeader
					WHERE ID = :msgId)

					$$$TRACE( srcComp _", ID: " _  msgId _ " is " _ tmdiff _" secs old")
					Do fileObj.WriteLine(srcComp _", ID: " _  msgId _ " is " _ tmdiff _" secs old and the Service Timout value: " _ timeOut)

				if ( tmdiff > timeOut)
				  {
					set pPriority = $$$eMessagePrioritySync 
					Set tSC = ##class(Ens.Queue).AbortItem(srcComp,pPriority,id)
					If $$$ISOK(tSC) {
					   $$$TRACE( "Abort: " _ id)
					   Do fileObj.WriteLine("Abort: " _ id)
					} Else {
					   $$$TRACE( "Abort failed for message with index "_id_": "_$$$StatusDisplayString(tSC))
					}
				  }

			}
  	}
  }


  $$$TRACE( "-- Done -- ")
  do fileObj.Close()
  return tSC
